// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0) && caller != address(this));
        depositAmount = bound(depositAmount, 1 ether, 100 ether);
        collectAmount = bound(collectAmount, 1, depositAmount);

        // Initialize and set MinSum to 1 wei (or less) so precondition is easy
        c.SetMinSum(1 wei);
        c.Initialized();

        // Deposit from caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(caller);

        // Collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        if (success) {
            uint256 balanceAfter = c.balances(caller);
            assertTrue(balanceAfter < balanceBefore, "Balance should decrease after successful Collect");
        }
    }
}

