pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmt, uint256 collectAmt) public {
        vm.assume(caller != address(0));
        depositAmt = bound(depositAmt, 2 ether, 100 ether);
        collectAmt = bound(collectAmt, 0, depositAmt);

        // Deposit some Ether
        vm.deal(caller, depositAmt);
        vm.prank(caller);
        c.Deposit{value: depositAmt}();

        // Compute sum of all balances before Collect
        uint256 sumBefore = c.balances(caller);
        // (only one participant for simplicity, but rule holds generally)

        uint256 contractBalanceBefore = address(c).balance;

        // Try Collect
        (bool success,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        if (success) {
            uint256 sumAfter = c.balances(caller);
            uint256 contractBalanceAfter = address(c).balance;
            assertTrue(sumAfter - sumBefore == contractBalanceAfter - contractBalanceBefore, "Sum of balances change should equal contract balance change");
        }
    }
}

