pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller1, uint256 deposit1, uint256 deposit2, uint256 _am) public {
        // Bound deposits to avoid overflow and to ensure enough Ether
        vm.assume(deposit1 >= 1 ether && deposit1 <= 100 ether);
        vm.assume(deposit2 >= 1 ether && deposit2 <= 100 ether);
        vm.assume(_am <= 100 ether);

        // Fund addresses
        vm.deal(caller1, deposit1);
        address caller2 = address(0x1234);
        vm.deal(caller2, deposit2);

        // Deposit from caller1
        vm.prank(caller1);
        c.Deposit{value: deposit1}();

        // Deposit from caller2
        vm.prank(caller2);
        c.Deposit{value: deposit2}();

        // Record balances before Collect
        uint256 balanceBefore1 = c.balances(caller1);
        uint256 balanceBefore2 = c.balances(caller2);

        // Determine which address has the smaller balance (the "minimum" key)
        address minKey;
        uint256 minBalance;
        if (balanceBefore1 < balanceBefore2) {
            minKey = caller1;
            minBalance = balanceBefore1;
        } else {
            minKey = caller2;
            minBalance = balanceBefore2;
        }

        // If minKey's balance is less than MinSum or less than _am, set MinSum low enough
        // and ensure _am <= balance, otherwise the call will revert and we skip
        if (minBalance < c.MinSum() || _am > minBalance) {
            // Adjust MinSum so that the precondition for the minimum-key holder holds
            vm.prank(address(0));
            c.SetMinSum(1);
        }

        // Now call Collect from caller1 with amount _am
        vm.prank(caller1);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, _am));

        // Check that if the call succeeded, the minimum-key's balance did not increase
        uint256 balanceAfter1 = c.balances(caller1);
        uint256 balanceAfter2 = c.balances(caller2);

        uint256 minAfter;
        if (minKey == caller1) {
            minAfter = balanceAfter1;
        } else {
            minAfter = balanceAfter2;
        }

        // General rule: The minimal balance among the two depositors (the key that was minimal before) must not be larger after Collect
        assertTrue(success ? (minAfter <= minBalance) : true);
    }
}

