pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount >= 1 ether);
        vm.assume(collectAmount >= 1 ether && collectAmount <= depositAmount);

        // Initialize the contract
        c.SetMinSum(1 ether);
        c.Initialized();

        // Deposit from caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(caller);

        // Try Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        uint256 balanceAfter = c.balances(caller);

        // The rule: If Collect succeeds, the caller's balance must decrease by exactly collectAmount
        if (success) {
            assertTrue(balanceAfter == balanceBefore - collectAmount, "Balance should decrease by collect amount");
        } else {
            // If it reverts, the balance must remain unchanged
            assertTrue(balanceAfter == balanceBefore, "Balance should stay same on revert");
        }
    }
}

