pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _am) public {
        // Ensure the MinSum is set to 1 ether (default)
        vm.assume(c.MinSum() == 1 ether);
        // Bound the amount to avoid overflow and ensure meaningful test
        vm.assume(_am <= 1 ether);
        // Give c some balance and deposit to sender
        vm.deal(address(c), 1 ether);
        // We need to first deposit so that balances[msg.sender] >= MinSum and >= _am
        // But we cannot call deposit directly because it requires msg.value and uses msg.sender
        // So we set up a prank with value
        vm.deal(address(this), 1 ether);
        // Deposit
        (bool success,) = address(c).call{value: 1 ether}("");
        require(success, "deposit failed");
        // Now call Collect with _am
        c.Collect(_am);
        // The rule: MinSum should still equal 1 ether (1e18 wei)
        assertTrue(c.MinSum() == 1 ether);
    }
}

