pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _am) public {
        // Bound _am to reasonable values to avoid overflow
        vm.assume(_am <= type(uint128).max);
        // Provide enough Ether to the contract for possible transfer
        vm.deal(address(c), _am);
        // Record MinSum before Collect
        uint256 minSumBefore = c.MinSum();
        // Call Collect
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _am));
        // Read MinSum after Collect
        uint256 minSumAfter = c.MinSum();
        // The rule: if Collect succeeded, MinSum must not have decreased
        // In the reference, SetMinSum is never called, so MinSum remains 0, which is not decreased.
        // In the mutant, SetMinSum body is empty so MinSum also remains 0. BUT the mutant bug is about MinSum being always 0? Actually mutant deletes SetMinSum body so MinSum is never set and stays 0.
        // However, the requirement is that P.MinSum() != M.MinSum() after Collect.
        // In P, SetMinSum(1 ether) is called in constructor? No, constructor does not call SetMinSum. So MinSum initially 0 in both.
        // The difference after Collect: in P, MinSum is 0; in M, MinSum is also 0? That would be equal.
        // Wait, the difference specification says "after a call to Collect(...) completes, the value of state variable MinSum differs: P.MinSum() != M.MinSum()."
        // That means that in the reference, calling Collect changes MinSum? But the reference code does not modify MinSum in Collect. So how could they differ?
        // Let's re-read: the mutant deletes SetMinSum function body, so SetMinSum does nothing. But the reference SetMinSum sets MinSum = _val.
        // The only way MinSum could differ after Collect is if Collect calls SetMinSum internally. It does not. So the only way MinSum differs is if something else changes MinSum before Collect.
        // Actually the bug scenario: the user calls Deposit, then Collect. But MinSum is set to 1 ether in contract code? No, MinSum is declared as 1 ether in state variable initialization.
        // Wait, MinSum = 1 ether is in the state variable declaration. So MinSum is always 1 ether unless SetMinSum is called.
        // The reference SetMinSum can change it, mutant SetMinSum does nothing. So after SetMinSum is called, reference's MinSum changes, mutant's stays at 1 ether.
        // But the test must end with Collect call, not SetMinSum.
        // The difference: after Collect, MinSum is different because before Collect, SetMinSum was called? But the test can only call Collect, not SetMinSum, because Collect is the entry.
        // The requirement says "Driven through the public/external entry Collect(uint256), P and M differ in this way: after a call to Collect(...) completes, the value of state variable MinSum differs: P.MinSum() != M.MinSum()."
        // That means that when we call Collect many times, the MinSum in P and M become different? But Collect does not change MinSum. So this can only be true if something else changes MinSum, but the test only calls Collect.
        // Actually, the test can call other functions before Collect, like SetMinSum and Initialized. But the rule says "driven through the public/external entry Collect(uint256)" meaning the final call is Collect, but we can call other things before.
        // The difference specification says the two contracts differ after a Collect call. That must be because the fuzz test calls SetMinSum first, then Collect. In reference, SetMinSum works, changing MinSum. In mutant, SetMinSum does nothing, so MinSum stays at 1 ether. Then after Collect, MinSum differs.
        // So the test should call SetMinSum at some point, then Initialized, then Deposit to set balance, then Collect. But the rule must be general.
        // The assertion: after Collect, MinSum is equal to the sum of initial MinSum and all SetMinSum calls that happened before Initialized.
        // But that is hard to capture in one assertion.
        // Let's simulate a simpler scenario: call SetMinSum with a random value, then call Initialized, then call Collect. For reference, MinSum becomes that random value; for mutant, MinSum stays at 1 ether. Then after Collect, MinSum values differ.
        // The rule: after Collect, MinSum is exactly the value set by the last SetMinSum call (if any) before Initialized.
        // This holds for reference (SetMinSum worked) but breaks for mutant (SetMinSum did nothing).
        // So test: call SetMinSum(_val), call Initialized, then call Collect. Then assert that c.MinSum() == _val.
        // But this assertion fails on the mutant because mutant's MinSum is still 1 ether.
        // However, we need the rule to be general over fuzz params, not hardcoded.
        // So: assert(c.MinSum() == _val) is invalid because _val is a fuzz parameter, and the reference does indeed set MinSum to _val (if SetMinSum called before Initialized).
        // So the rule holds on reference for all _val. But the mutant fails because MinSum never changes.
        uint256 _val = _am; // reuse _am as MinSum value to set
        // But we need to ensure _val is not larger than some limit? vm.assume already limits _am to 128 bits.
        c.SetMinSum(_val);
        c.Initialized();
        // Now we have enough balance: give msg.sender some Ether and call Deposit
        // But for Collect to succeed, we need balance >= MinSum and >= _am.
        // We'll just call Collect even if it reverts; the rule is about MinSum after call, regardless of revert.
        c.Collect(_am);
        // The rule: MinSum should equal _val
        assertTrue(c.MinSum() == _val, "MinSum should be _val");
    }
}

